package com.crm.fees.service;import com.crm.security.AuthenticatedUserPrincipal;import org.springframework.security.core.context.SecurityContextHolder;
public final class FeeAuthorization {private FeeAuthorization(){} public static long admin(){var p=AuthenticatedUserPrincipal.require(SecurityContextHolder.getContext().getAuthentication());if(p.authorities().stream().noneMatch(a->java.util.Set.of("ROLE_ADMIN","ROLE_SUPER_ADMIN").contains(a.getAuthority())))throw new org.springframework.security.access.AccessDeniedException("Administrative access required");return p.userId();}}